    # Initialize the grid with zeros
    grid = [[0] * (N + 1) for _ in range(N + 1)]

    # Fill the grid with values from grid_values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x][y] = value

    # DP table to store maximum values
    dp = [[[[-1] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)] for _ in range(N + 1)]

    # Base case
    dp[1][1][1][1] = 2 * grid[1][1]

    # Fill the DP table
    for i1 in range(1, N + 1):
        for j1 in range(1, N + 1):
            for i2 in range(1, N + 1):
                j2 = i1 + j1 - i2
                if j2 < 1 or j2 > N:
                    continue
                if grid[i1][j1] == -1 or grid[i2][j2] == -1:
                    continue
                if dp[i1][j1][i2][j2] == -1:
                    current_value = grid[i1][j1]
                    if i1 != i2 or j1 != j2:
                        current_value += grid[i2][j2]
                    dp[i1][j1][i2][j2] = max(
                        dp[i1 - 1][j1][i2 - 1][j2],
