def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product that can be obtained by inserting K multiplication signs into the number string.

    :param num_str: String representing the number
    :param N: Length of the number string
    :param K: Number of multiplication signs to insert
    :return: The maximum product
    """
    # Edge case: If K is 0, no multiplication signs are needed, return the number itself
    if K == 0:
        return int(num_str)

    # Edge case: If K is greater than or equal to N-1, we can only form single digit numbers, return the maximum digit
    if K >= N - 1:
        return int(max(num_str))

    # Dynamic programming table to store the maximum product up to each position with a certain number of multiplication signs
    dp = [[0] * (K + 1) for _ in range(N)]

    # Initialize the first column of the dp table
    for i in range(N):
        dp[i][0] = int(num_str[:i+1])

    # Fill the dp table
    for k in range(1, K + 1):
        for i in range(k, N):
            for j in range(k-1, i):
                dp[i][k] = max(dp[i][k], dp[j][k-1] * int(num_str[j+1:i+1]))

    # The result is the maximum product for the entire string with K multiplication signs
    return dp[N-1][K]

