def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    def count_separated(row_cut, col_cut, chatting_pairs):
        separated = 0
        for x1, y1, x2, y2 in chatting_pairs:
            if (x1 <= row_cut and x2 > row_cut) or (x1 > row_cut and x2 <= row_cut):
                separated += 1
            elif (y1 <= col_cut and y2 > col_cut) or (y1 > col_cut and y2 <= col_cut):
                separated += 1
        return separated

    row_cuts = [0] * (M + 1)
    col_cuts = [0] * (N + 1)

    for x1, y1, x2, y2 in chatting_pairs:
        if x1 != x2:
            min_row = min(x1, x2)
            row_cuts[min_row] += 1
        if y1 != y2:
            min_col = min(y1, y2)
            col_cuts[min_col] += 1

    row_indices = sorted(range(1, M), key=lambda x: row_cuts[x], reverse=True)[:K]
    col_indices = sorted(range(1, N), key=lambda x: col_cuts[x], reverse=True)[:L]

    row_indices.sort()
    col_indices.sort()

    return (' '.join(map(str, row_indices)), ' '.join(map(str, col_indices)))

