def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        return 0
    if m == 0:
        return 1 if n == 1 else 0

    # dp[i][j] will be the number of ways to be at position j after i passes
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]

    return dp[m][0] % 1000000007

