def count_partitions(n: int, k: int, x: int) -> int:
    # Helper function to perform the recursive counting
    def count_partitions_recursive(n, k, x, memo):
        # Base cases
        if n < k * x:
            return 0
        if k == 1:
            if n >= x:
                return 1
            else:
                return 0

        # Check if the result is already computed
        if (n, k, x) in memo:
            return memo[(n, k, x)]

        # Recursive case: include at least x in the current part and partition the rest
        count = 0
        for i in range(x, n - k + 1 + x):  # i is the value of the current part
            count += count_partitions_recursive(n - i, k - 1, i, memo)

        # Store the result in the memoization dictionary
        memo[(n, k, x)] = count
        return count

    # Initialize memoization dictionary
    memo = {}

    # Start the recursive counting
    return count_partitions_recursive(n, k, x, memo)

