def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    # Create a dictionary to store the index of each value in the inorder traversal
    index_map = {value: index for index, value in enumerate(inorder)}

    def helper(in_start, in_end, post_start, post_end):
        if in_start > in_end or post_start > post_end:
            return ""

        # The last element in postorder is the root
        root_val = postorder[post_end]
        root_index = index_map[root_val]

        # Calculate the size of the left subtree
        left_tree_size = root_index - in_start

        # Recursively build the left and right subtrees
        left_subtree = helper(in_start, root_index - 1, post_start, post_start + left_tree_size - 1)
        right_subtree = helper(root_index + 1, in_end, post_start + left_tree_size, post_end - 1)

        # Return the preorder traversal
        return root_val + left_subtree + right_subtree

    # Build the tree using the helper function
    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

