def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a list to store the maximum volume that can be achieved with given capacity
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: zero volume can always be achieved with zero items

    # Iterate over each volume
    for volume in volumes:
        # Update the dp array from back to front to avoid overwriting results from the same iteration
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved without exceeding V
    max_achievable_volume = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_achievable_volume = j
            break

    # The minimum remaining space is the total capacity minus the maximum achievable volume
    return V - max_achievable_volume

